insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q1',null,'c-vikram','After 15 years of ECC FI/CO history, what is the sanest S/4HANA cutover path?','We run ECC 6.0 with a thin custom code base, and the board wants an S/4HANA go-live by 2027. DMO, blue-green, or digital coexistence — what do you actually recommend at mid-market scale, and what surprises teams most at cutover?','s4onprem','fi','',false,true,9,0,(extract(epoch from now())*1000)::bigint-432000001) on conflict (id) do nothing;
