insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q1a1','q1',null,'c-ahmed','Digital coexistence only if you''re forced by legacy interfaces. Otherwise DMO with 2–3 parallel runs; start cleansing open items 6 months ahead — dirty open items are what blow up cutover, not the config.',true,true,6,0,(extract(epoch from now())*1000)::bigint-172800001) on conflict (id) do nothing;
