insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q2a1','q2',null,'c-diego','Config-level it''s a swap (MM takes over). The real pain is the history: 10 years of assortment and location data. We archived everything before the last 12 months and the load went from 3 weeks to 3 days.',true,true,5,0,(extract(epoch from now())*1000)::bigint-345600001) on conflict (id) do nothing;
