insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q3a1','q3',null,'c-meera','ECP on ECC reading from SF EC is still the mainstream pattern. Check the cloud ECP country coverage for your countries first — if all your pays are covered, go cloud ECP and drop ECC payroll entirely.',true,true,6,0,(extract(epoch from now())*1000)::bigint-518400001) on conflict (id) do nothing;
