insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q4',null,'co-siwa','Hiring a FICO consultant for our billing + S/4HANA conversion — what should they prove in the first 90 days?','We are hiring a FICO consultant for our S/4HANA conversion, which includes a billing modernisation. What should a candidate prove in the first 90 days for you to trust them with the cutover workstream?','s4onprem','fi','',false,true,12,0,(extract(epoch from now())*1000)::bigint-604800001) on conflict (id) do nothing;
