insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q4a1','q4',null,'c-vikram','Three things: (1) a conversion readiness assessment of your FI data within 30 days — not a generic deck, actual exception reports. (2) A data-cleansing KPI they can drive down monthly. (3) A parallel close they own end-to-end. Anyone who can deliver those three is worth their rate.',true,true,7,0,(extract(epoch from now())*1000)::bigint-259200001) on conflict (id) do nothing;
