insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q5',null,'c-fatima','GRC Access Control: separate system or on the S/4HANA stack? And certification campaign gotchas in the GCC?','Deciding where to put GRC Access Control — a separate system or on the S/4HANA stack — and planning a certification campaign across the Kingdom. Which has served you better, and what are the GCC-specific gotchas?','s4onprem','securitygrc','',false,true,7,0,(extract(epoch from now())*1000)::bigint-1296000001) on conflict (id) do nothing;
