insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q5a1','q5',null,'c-omar','Stack choice matters less than the certification process. Our CBA (critical business actions) definitions did the heavy lifting, not the tool version. GCC gotcha: regulators increasingly want the audit trail in-country — check where GRC stores its evidence before you size the deployment.',true,true,4,0,(extract(epoch from now())*1000)::bigint-432000001) on conflict (id) do nothing;
