insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q6',null,'c-priya','Embedded S/4HANA EWM vs decentralized (DM) — 3 warehouses, mostly batch. What did you pick and why?','Three warehouses, mostly batch processes, no high-velocity picking. Do you embed EWM in S/4HANA or go decentralized? Curious what people at our scale actually pick and why.','s4onprem','ewm','',false,true,5,0,(extract(epoch from now())*1000)::bigint-1555200001) on conflict (id) do nothing;
