insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q6a1','q6',null,'c-nour','Embedded at that scale. DM only pays off with many sites, 24/7 wave execution and a big WCS team. Three batch warehouses: embedded — less integration surface, cheaper to run.',true,true,3,0,(extract(epoch from now())*1000)::bigint-691200001) on conflict (id) do nothing;
