insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q6a2','q6',null,'c-diego','Agreed — and one more: if you later add a cross-dock or a DC with high-velocity picks, you can start DM there without touching the others.',false,true,1,0,(extract(epoch from now())*1000)::bigint-864000001) on conflict (id) do nothing;
