insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q7',null,'c-nour','TM routing in GCC fuel distribution — carrier onboarding is painful. Any patterns that worked?','Fuel distribution across the Gulf — our TM rollout keeps hitting the same wall: carrier onboarding. New carrier, new two weeks of calls and spreadsheet mapping. Anyone got a pattern that made onboarding a checklist instead of an event?','s4onprem','tm','',false,true,8,0,(extract(epoch from now())*1000)::bigint-1728000001) on conflict (id) do nothing;
