insert into public.votes(kind,item_id,voter,owner) values ('q','q7','c-priya',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q7a1','q7',null,'c-rahul','Two things fixed it for us: (1) deterministic routing — no AI magic, just rule-based segments by commodity/weight so planners trust it; (2) load types per commodity with a carrier confirmation step before dispatch. Onboarding a new carrier went from 2 weeks of calls to a checklist.',true,true,4,0,(extract(epoch from now())*1000)::bigint-864000001) on conflict (id) do nothing;
