insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q8',null,'c-raja','SuccessFactors Employee Central rollout across three Gulf countries: which localizations actually exist for payroll?','Rolling out Employee Central across three Gulf countries next year. HR-data localisation seems covered, but which localisations actually exist for payroll, and where do you run into "check with your partner" answers?','successfactors','ec','',false,true,10,0,(extract(epoch from now())*1000)::bigint-2160000001) on conflict (id) do nothing;
