insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q8a1','q8',null,'c-meera','SF EC localizations cover HR data and leave differently per country — KSA has the deepest package (WPS, Iqama fields are there). For payroll itself, budget the ECP per-country check: Saudi and UAE are covered, but Oman we ran on ECC ECP. Always verify the exact country+payroll combo before you promise a timeline.',true,true,7,0,(extract(epoch from now())*1000)::bigint-950400001) on conflict (id) do nothing;
