insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q9',null,'c-omar','ABAP: what is the realistic effort to prep custom code for S/4HANA? Our ATC run came back with 4,000 findings.','ATC for S/4HANA came back with 4,000 findings across our custom code. Before we budget the rework — how do you realistically triage this? And what does the effort usually look like per 1,000 findings?','s4onprem','abap','',false,true,10,0,(extract(epoch from now())*1000)::bigint-2592000001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q9','c-max',null) on conflict do nothing;
