insert into public.votes(kind,item_id,voter,owner) values ('q','q9','c-ahmed',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q9','c-vikram',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q9a1','q9',null,'c-max','Don''t budget per finding. Triage by severity + usage first — in our last two conversions 80% of findings were noise (deprecated syntax nobody calls). What remains is usually 3–6 weeks of rework per 1,000 *used* procedures, not per finding. And plan 2–3× your naive estimate for the rewrite.',true,true,5,0,(extract(epoch from now())*1000)::bigint-1209600001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q9a1','c-omar',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q9a1','c-diego',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q9a1','c-vikram',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q9a2','q9',null,'c-diego','Also: run the usage check (SCU) before the ATC even. We deleted 200+ unused objects and the ATC count halved for free.',false,true,2,0,(extract(epoch from now())*1000)::bigint-1555200001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q9a2','c-omar',null) on conflict do nothing;
insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q10',null,'co-indus','Still on ECC 6.0: should we care about SAP''s extended maintenance pricing after 2027?','We still run ECC 6.0 for a mid-market client, and the extended maintenance pricing after 2027 just landed. Should we treat this as a conversion trigger, or is there a sane middle path?','ecc','fi','',false,true,13,0,(extract(epoch from now())*1000)::bigint-3024000001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q10','c-vikram',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q10','c-priya',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q10','c-ahmed',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q10a1','q10',null,'c-vikram','Yes — treat it as the forcing function it is. Extended maintenance is priced to push you off, and it compounds yearly. Model three scenarios (convert / extend / hybrid) and let the 2027–2028 line items decide. Most clients we model land on conversion.',true,true,8,0,(extract(epoch from now())*1000)::bigint-1382400001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q10a1','co-indus',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q10a1','c-priya',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q10a1','c-max',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q10a2','q10',null,'c-priya','If the full conversion is too big for your budget, the phased module-by-module approach (FI/CO first, then the rest) keeps the extended-maintenance exposure down where it matters least.',false,true,4,0,(extract(epoch from now())*1000)::bigint-1296000001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q10a2','c-vikram',null) on conflict do nothing;
insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q11',null,'c-anita','Ariba Sourcing feeding S/4HANA P2P: the two integration pain points we always hit','Integrating Ariba Sourcing with S/4HANA P2P for a retail client. We keep hitting the same two pain points — field mismatches in source-to-contract data, and version drift between integration releases. Anyone have patterns that dodged both?','ariba','sourcing','',false,true,6,0,(extract(epoch from now())*1000)::bigint-2419200001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q11','c-diego',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q11','c-rahul',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q11a1','q11',null,'c-diego','You''ll be glad to hear both are avoidable. (1) Source-to-contract data lands in S/4 with field mismatches — map the Ariba item fields to your PO segments early, don''t wait for integration week. (2) The S/4HANA Ariba integration suite (not the old RFC) handles 90% of the flows out of the box — only build custom for the real gaps.',true,true,4,0,(extract(epoch from now())*1000)::bigint-1036800001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q11a1','c-anita',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q11a1','c-rahul',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q11a1','c-meera',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q11a2','q11',null,'c-rahul','Adding: keep the Sourcing event log accessible to your S/4 team during cutover — half our "data errors" were Sourcing-side and invisible until we compared timestamps.',false,true,1,0,(extract(epoch from now())*1000)::bigint-1728000001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q11a2','c-anita',null) on conflict do nothing;
insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q12',null,'c-diego','BTP: when does "side-by-side" extension actually beat embedded ABAP on S/4HANA?','The BTP vs embedded ABAP debate again. When does side-by-side extension on BTP actually beat an embedded extension on S/4HANA — and when do teams put it on BTP by mistake?','btp','integration','',false,true,7,0,(extract(epoch from now())*1000)::bigint-3456000001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q12','c-max',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q12','c-rahul',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q12a1','q12',null,'c-max','Rule of thumb: if the extension needs its own release cycle, its own scale, or talks to a third party — BTP. If it''s a UI or logic change that must stay transactionally consistent with S/4HANA — embedded, every time. The day you find yourself versioning a side app in lockstep with an S/4 release, you put it on BTP by mistake.',true,true,4,0,(extract(epoch from now())*1000)::bigint-1641600001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q12a1','c-diego',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('a','q12a1','c-rahul',null) on conflict do nothing;
insert into public.questions(id,owner,author,title,body,product_id,module_id,topic,anonymous,sample,votes_base,milestone,created_ts) values ('q13',null,'c-ahmed','MM: 15 years of purchase history — what do we actually bring into S/4HANA?','15 years of purchase history, open POs, GR/IR and a fairly rich vendor master heading into S/4HANA. What do you actually bring across, and what do you archive instead?','s4onprem','mm','',false,true,7,0,(extract(epoch from now())*1000)::bigint-345600001) on conflict (id) do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q13','c-priya',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q13','c-nour',null) on conflict do nothing;
insert into public.votes(kind,item_id,voter,owner) values ('q','q13','c-diego',null) on conflict do nothing;
insert into public.answers(id,question_id,owner,author,body,accepted,sample,votes_base,milestone,created_ts) values ('q13a1','q13',null,'c-priya','Open POs + GR/IR, and the last 2–3 years of purchase history for condition and MRP relevance. Everything older: archive, don''t migrate. We brought 18 months for a client with heavy consignment, and their MRP was happy with it. Full 15-year history will only slow you down and hurt nothing.',true,true,5,0,(extract(epoch from now())*1000)::bigint-172800001) on conflict (id) do nothing;
