insert into public.articles(id,owner,author,title,url,body,product_id,module_id,topic,sample,votes_base,milestone,created_ts) values ('a1',null,'c-vikram','The five things we wish we''d prepared before our S/4HANA cutover weekend','https://sapfieldnotes.example/s4hana-cutover-checklist','Short version: open items, clean master data, a rehearsed rollback, a named owner for every ticket, and a freeze on changes two weeks prior. The cutover itself is the easy part — everything before it is the real work.','s4onprem','fi','',true,17,0,(extract(epoch from now())*1000)::bigint-259200001) on conflict (id) do nothing;
