insert into public.articles(id,owner,author,title,url,body,product_id,module_id,topic,sample,votes_base,milestone,created_ts) values ('a2',null,'c-ahmed','What SAP''s ECC extended maintenance really means for your 2026 budget','https://sapfieldnotes.example/ecc-extended-maintenance-budget','Extended maintenance is priced to be an argument, not an option. It''s the line item that finally gets the board to fund the conversion — read the pricing page, do the 3-year math, and bring that number to your next budget meeting.','ecc','co','',true,16,0,(extract(epoch from now())*1000)::bigint-518400001) on conflict (id) do nothing;
