insert into public.articles(id,owner,author,title,url,body,product_id,module_id,topic,sample,votes_base,milestone,created_ts) values ('a4',null,'c-max','A field guide to the ATC checks that actually bite in S/4HANA','https://sapfieldnotes.example/atc-field-guide','ABAP Test Cockpit findings are grouped by how much they''ll hurt you. The ones that actually block cutover are a short list — dynamic SQL into changed tables, BAPIs that lost their signatures, and a few OData quirks. Triage by severity, not by count.','s4onprem','abap','',true,16,0,(extract(epoch from now())*1000)::bigint-1036800001) on conflict (id) do nothing;
