insert into public.articles(id,owner,author,title,url,body,product_id,module_id,topic,sample,votes_base,milestone,created_ts) values ('a6',null,'c-rahul','Datasphere vs SAC data models: what we learned migrating 120 BW queries','https://sapfieldnotes.example/datasphere-sac-migration','Datasphere for the semantic layer and reusable flows, SAC for the front end. The migration taught us the models matter less than the ownership model — every query needs a named owner in Datasphere or it rots within a release.','data','datasphere','',true,10,0,(extract(epoch from now())*1000)::bigint-1900800001) on conflict (id) do nothing;
